// === Tab: mySketch ===
//let Test
let NoP = 300;

let mass = new Array(NoP);
let x = new Array(NoP);
let y = new Array(NoP);
let velocity_x = new Array(NoP);
let velocity_y = new Array(NoP);

function setup() {
  background(0);
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
  for (i = 0; i < NoP; i++) {
    mass[i] = random(0.25, 0.5); //*pow(10, 12);
    x[i] = random(width/3, width*2/3);
    y[i] = random(height/3, height*2/3);
    velocity_x[i] = random(-2.0, 2.0);
    velocity_y[i] = random(-2.0, 2.0);
  }
}

function draw() {
  background(0);

  for (i = 0; i < NoP; i++) {
    collide(i);
    updateVelocity(i);
    updatePosition(i);
    drawEllipse(i);
  }
}

function drawEllipse(index) {
  let w = radius(index)*2.0;
  fill(255);
  ellipse(x[index], y[index], w, w);
}

function radius(index) {
	return 4.0*pow((3.0*mass[index])/(PI*4.0), 1/3);
}

function collide(index) {
	if (mass[index] > 0.0) {
  	for (i = 0; i < NoP; i++) {
			if (i != index && mass[index] >= mass[i]) {
    		let delta_d = dist(x[index], y[index], x[i], y[i]);
    		let collision_d = radius(index) + radius(i);
    		if (delta_d < collision_d) {
      		velocity_x[index] = (mass[index]*velocity_x[index] + mass[i]*velocity_x[i])/(mass[index]+mass[i]);
      		velocity_y[index] = (mass[index]*velocity_y[index] + mass[i]*velocity_y[i])/(mass[index]+mass[i]);
      		velocity_x[i] = 0.0;
      		velocity_y[i] = 0.0;
      		mass[index] += mass[i];
      		mass[i] = 0.0;
    		}
			}
  	}
	}
}

function updatePosition(index) {
  x[index] += velocity_x[index];
  y[index] += velocity_y[index];
}

function updateVelocity(index) {
  for (i = 0; i < NoP; i++) {
    if (i != index) {
      let delta_y = y[index] - y[i];
      let delta_x = x[index] - x[i];

      var delta_d = sqrt(pow(delta_y,2) + pow(delta_x,2));
      let theta = atan(delta_y/delta_x);
      let a = (6.67*pow(10,-11))*(mass[i]*pow(10,11))/(pow(delta_d,2));

      if (delta_x < 0.0) {
        velocity_x[index] += a*cos(theta);
        velocity_y[index] += a*sin(theta);
      } else {
        velocity_x[index] -= a*cos(theta);
        velocity_y[index] -= a*sin(theta);
      }
    }
  }
}

